using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_Response_Is_Relevant()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one response message.");

        var evaluator = new RelevanceTruthAndCompletenessEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            chatClient);

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Coherent()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var evaluator = new CoherenceEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            chatClient);

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Fluent()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of regular exercise.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var evaluator = new FluencyEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            chatClient);

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }
}

